/*
 * A216273  Triangle generated by Sum_{n>=1, k=1..n} T(n,k)*x^n*y^k/n = log(1
 *          + Sum_{n>=1} y*x^(n^2)), where coefficients are read by rows.
 * https://oeis.org/A216273
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  tabl, sign
 * Formula:   The sequence a(n) is obtained by flattening the triangle *
 *            T(n,k) (n ≥ 1, 1 ≤ k ≤ n) read row‑wise. The triangle entries
 *            are * defined by T(n,k) = n * (-1)^{k-1}/k * C(n,k), * where
 *            C(n,k) is the number of *ordered* k‑tuples of positive integers
 *            * whose squares sum to n. This follows from the gen...
 * Range:     i8 n <= 71, i16 n <= 425, i32 n <= 1035, i64 n <= 1035,
 *            i128 n <= 1035, big any n
 * Helpers:   append_candidate
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdint.h>
#include "../utils/append_candidate.h"

/* Length and dynamic array for the output sequence */
static seq_t *seq_vals = NULL;
static size_t seq_len = 0, seq_cap = 0;

/* Dynamic table of counts C(n,k).  dp[n][k] holds the number of ordered
 * k‑tuples of squares summing to n.  dp[0][0] = 1, all other dp[0][k>0] = 0. */
static seq_t **dp = NULL;   /* array of pointers to row arrays */
static size_t dp_rows = 0;  /* number of rows currently allocated (dp[0]..dp[dp_rows-1]) */

/* The next row (n) that has not yet been generated. */
static idx_t next_row = 1;

/* Ensure the dp table contains rows up to 'n' (inclusive).  The row for
 * index n is allocated but its entries are zeroed (calloc).  dp[0][0] is
 * set to 1 once during the first call. */
static void ensure_dp_rows(idx_t n)
{
    if (dp_rows > n) return;          /* already sufficient */
    /* Resize the dp pointer array */
    dp = (seq_t**)realloc(dp, (n + 1) * sizeof(seq_t*));
    for (idx_t i = dp_rows; i <= n; ++i) {
        dp[i] = (seq_t*)calloc((size_t)(i + 1), sizeof(seq_t)); /* dp[i][0..i] = 0 */
    }
    /* Initialize the base case once */
    if (dp_rows == 0) {
        dp[0][0] = (seq_t)1;
    }
    dp_rows = n + 1;
}

/* Generate the triangle row for index 'r' (r ≥ 1) and append the
 * corresponding T(r,k) values to the output sequence.  This function
 * uses the current dp table and updates it with the new row. */
static void generate_row(idx_t r)
{
    /* Make sure that dp contains rows up to r-1 (they should exist) */
    ensure_dp_rows(r);

    /* For each k = 1..r compute the count C(r,k) */
    for (idx_t k = 1; k <= r; ++k) {
        seq_t sum = 0;
        for (idx_t t = 1; (uint64_t)t * t <= r; ++t) {
            idx_t s = (idx_t)(t * t);
            if ((k - 1) <= (r - s)) {
                sum += dp[r - s][k - 1];
            }
        }
        dp[r][k] = sum;
    }

    /* Now compute T(r,k) and append to seq_vals */
    for (idx_t k = 1; k <= r; ++k) {
        seq_t count = dp[r][k];
        seq_t prod   = (seq_t)r * count;          /* n * C(n,k) */
        seq_t quot   = prod / (seq_t)k;           /* division is exact by construction */
        int   sign   = (k & 1) ? 1 : -1;           /* (-1)^(k-1) */
        seq_t val    = (sign > 0) ? quot : -quot;
        append_candidate(&seq_vals, &seq_len, &seq_cap, val);
    }
}

/* Public function requested by the build system. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* not used, but safe */
    /* Generate rows until we have at least n terms. */
    while (seq_len < (size_t)n) {
        generate_row(next_row);
        ++next_row;
    }
    return seq_vals[n - 1];
}
